package com.rikkeibank.customer.domain; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(uniqueConstraints={@UniqueConstraint(columnNames="email"),@UniqueConstraint(columnNames="nationalId")}) public class Customer{@Id private UUID id;@Column(nullable=false)private String fullName;@Column(nullable=false)private String email;@Column(nullable=false)private String phone;@Column(nullable=false)private String nationalId;private LocalDate dateOfBirth;private String address;@Column(nullable=false)private boolean active=true;private Instant createdAt;protected Customer(){}public Customer(String n,String e,String p,String nid,LocalDate dob,String a){id=UUID.randomUUID();update(n,e,p,nid,dob,a,true);createdAt=Instant.now();}public void update(String n,String e,String p,String nid,LocalDate dob,String a,boolean ac){fullName=n;email=e;phone=p;nationalId=nid;dateOfBirth=dob;address=a;active=ac;}public UUID getId(){return id;}public String getFullName(){return fullName;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getNationalId(){return nationalId;}public LocalDate getDateOfBirth(){return dateOfBirth;}public String getAddress(){return address;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}}

